import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../state/providers.dart'; import '../../widgets/app_scaffold.dart';
class CollaboratorsScreen extends ConsumerStatefulWidget{ const CollaboratorsScreen({super.key,required this.familyId}); final String familyId; @override ConsumerState<CollaboratorsScreen> createState()=>_S();} class _S extends ConsumerState<CollaboratorsScreen>{ final email=TextEditingController(); @override Widget build(BuildContext context){ final fam=ref.watch(familyProvider(widget.familyId)).valueOrNull; final invites=ref.watch(invitesProvider(widget.familyId)).valueOrNull??[]; return AppScaffold(title:'Collaborators', familyId:widget.familyId, child:ListView(padding:const EdgeInsets.all(16), children:[for(final e in fam?.roles.entries??const <MapEntry<String,String>>[]) Card(child:ListTile(leading:const Icon(Icons.person), title:Text(e.key), trailing:Chip(label:Text(e.value)))), for(final i in invites) Card(child:ListTile(leading:const Icon(Icons.schedule_send), title:Text(i), trailing:const Chip(label:Text('pending')))), FilledButton.icon(onPressed:()=>showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Invite collaborator'), content:TextField(controller:email, decoration:const InputDecoration(labelText:'Email')), actions:[TextButton(onPressed:()=>Navigator.pop(c), child:const Text('Cancel')), FilledButton(onPressed:() async{await ref.read(repositoryProvider).inviteCollaborator(widget.familyId,email.text); if(c.mounted)Navigator.pop(c);}, child:const Text('Invite'))])), icon:const Icon(Icons.mail), label:const Text('Invite'))]));}}
